#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the motions' bucket and the voice (#567, ADR-0066; runbook:
# docs/ops/motions.md). A Scaleway Object Storage bucket in fr-par, named
# media.jobbbox.ai, holds the Explainer Videos (MP4, VTT, transcripts,
# posters), served over HTTPS at https://media.jobbbox.ai through Scaleway Edge
# Services. The `motions` workflow publishes to it with an API key kept in the
# repository's secrets, and reads its voice provider's key from them too.
# ──────────────────────────────────────────────────────────────────────────
TOTAL_STAGES=7
# Run from anywhere: the CORS file is read from the repository.
cd "$(dirname "$0")/../.."
BUCKET="media.jobbbox.ai"
ENDPOINT="https://s3.fr-par.scw.cloud"

banner "Motions: the media.jobbbox.ai bucket and the synthetic voice (#567)"

stage "Scaleway account and project"
say "The bucket lives in a Scaleway project of Jobbbox's own, in the Paris region (fr-par)."
open_url "https://console.scaleway.com/project"
step "Sign in (or create the organisation's account), then create a project named « jobbbox-media » (or pick an existing one)."
step "Billing: the organisation needs a payment method before Object Storage can be used."
confirm "Project ready?" || SKIPPED+=("Create the Scaleway project for the bucket")

stage "An API key for the motions workflow"
say "The workflow publishes with an IAM application of its own, allowed only on Object Storage."
open_url "https://console.scaleway.com/iam/applications"
step "Create an application « motions-workflow », then a policy for it: ObjectStorageFullAccess, scoped to the project above."
step "On the application, generate an API key; choose the project above as its preferred Object Storage project."
ask SCW_ACCESS_KEY "Paste its access key (SCW…):"
ask_secret SCW_SECRET_KEY "Paste its secret key:"
set_secret MOTIONS_S3_ACCESS_KEY "$SCW_ACCESS_KEY"
set_secret MOTIONS_S3_SECRET_KEY "$SCW_SECRET_KEY"

stage "Create the bucket"
export AWS_ACCESS_KEY_ID="$SCW_ACCESS_KEY" AWS_SECRET_ACCESS_KEY="$SCW_SECRET_KEY" AWS_DEFAULT_REGION=fr-par
unset SCW_SECRET_KEY
if command -v aws >/dev/null 2>&1; then
  if aws --endpoint-url "$ENDPOINT" s3api head-bucket --bucket "$BUCKET" >/dev/null 2>&1; then
    say "The bucket $BUCKET already exists."
  elif aws --endpoint-url "$ENDPOINT" s3api create-bucket --bucket "$BUCKET" >/dev/null; then
    printf '  %s✓ created%s bucket %s in fr-par\n' "$GREEN" "$RESET" "$BUCKET"
  else
    SKIPPED+=("Create the bucket $BUCKET in fr-par (console: Object Storage › Create bucket)")
  fi
  # The Help Centre's <track> reads the captions across origins (#568): GET from the app's origins only.
  if aws --endpoint-url "$ENDPOINT" s3api put-bucket-cors --bucket "$BUCKET" --cors-configuration file://packages/motions/bucket/cors.json >/dev/null; then
    printf '  %s✓ set%s CORS for jobbbox.ai and staging.jobbbox.ai\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("Set the bucket's CORS from packages/motions/bucket/cors.json")
  fi
else
  warn "the aws CLI is missing: create the bucket in the console instead."
  open_url "https://console.scaleway.com/object-storage/buckets"
  step "Create bucket: name $BUCKET, region Paris (fr-par), visibility private (the workflow makes each file public-read)."
  SKIPPED+=("Set the bucket's CORS from packages/motions/bucket/cors.json (aws s3api put-bucket-cors)")
  pause "Press Enter once the bucket exists"
fi
unset AWS_SECRET_ACCESS_KEY

stage "Serve it at https://media.jobbbox.ai (Edge Services)"
say "Object Storage serves no certificate for a custom domain: Edge Services does, with a managed Let's Encrypt one."
open_url "https://console.scaleway.com/edge-services"
step "Create a pipeline whose origin is the bucket $BUCKET (fr-par)."
step "Add the custom domain media.jobbbox.ai, with a managed certificate. Keep caching on (each video's folder never changes)."
ask EDGE_TARGET "Paste the CNAME target Edge Services gives for media.jobbbox.ai:"

stage "DNS at GoDaddy"
open_url "https://dcc.godaddy.com/control/portfolio/jobbbox.ai/settings?tab=dns"
step "Add a record: type CNAME, name media, value ${EDGE_TARGET}, TTL 1 hour."
pause "Press Enter once it is saved"
if command -v dig >/dev/null 2>&1; then
  note "media.jobbbox.ai now answers: $(dig +short CNAME media.jobbbox.ai | head -n1)"
fi
step "Back in Edge Services, wait until the certificate of media.jobbbox.ai is « Ready » (a few minutes after the DNS)."
confirm "Certificate ready?" || SKIPPED+=("Wait for the Edge Services certificate of media.jobbbox.ai")

stage "The voice providers' keys"
say "The product owner chooses the voice by ear: the workflow renders samples from every provider whose key is set."
say "Leave a key empty to skip that provider. The keys are secrets of the workflow only, never of the app."
ask_secret EL_KEY "ElevenLabs API key (elevenlabs.io › Developers › API keys), or Enter to skip:"
[[ -n "$EL_KEY" ]] && set_secret MOTIONS_ELEVENLABS_API_KEY "$EL_KEY"
ask_secret AZ_KEY "Azure AI Speech key (resource in France Central › Keys and Endpoint), or Enter to skip:"
[[ -n "$AZ_KEY" ]] && set_secret MOTIONS_AZURE_SPEECH_KEY "$AZ_KEY"
ask_secret GG_KEY "Google Cloud Text-to-Speech API key (restricted to that API), or Enter to skip:"
[[ -n "$GG_KEY" ]] && set_secret MOTIONS_GOOGLE_TTS_API_KEY "$GG_KEY"
unset EL_KEY AZ_KEY GG_KEY

stage "First run"
step "Run the samples only: gh workflow run motions.yml -f motions=all -f fixtures=true -f publish=false -f voice-samples=true"
step "Listen to the samples (the run's « motions » artifact, voice-samples/), then name the chosen voice:"
note "gh variable set MOTIONS_VOICE_PROVIDER --body <elevenlabs|azure|google>"
note "gh variable set MOTIONS_VOICE_FR --body <voice> ; gh variable set MOTIONS_VOICE_EN --body <voice>"
step "Then publish the test Motion Script with that voice: gh workflow run motions.yml -f motions=essai-candidatures,essai-capture-cassee -f fixtures=true"
note "Its summary shows essai-candidatures published, FR and EN, and essai-capture-cassee broken, with its warning."
step "Check a published file opens: https://media.jobbbox.ai/manifest.json"
confirm "manifest.json opens?" || SKIPPED+=("Run the motions workflow with the fixtures and open https://media.jobbbox.ai/manifest.json")

finish
